class TlObject:
    """Base class for TL Objects"""

    def __getitem__(self, item):
        if item == "@type":
            return self.getType()

        return self.__dict__[item]

    def __setitem__(self, item, value):
        self.__dict__[item] = value

    def __bool__(self):
        return not isinstance(self, Error)

    @property
    def is_error(self):  # for backward compatibility
        return isinstance(self, Error)

    @property
    def limited_seconds(self):
        if self.is_error and self.code == 429:
            return pytdbot.utils.get_retry_after_time(self.message)
        else:
            return 0

    @classmethod
    def getType(cls):
        raise NotImplementedError

    @classmethod
    def getClass(cls):
        raise NotImplementedError

    def to_dict(self) -> dict:
        raise NotImplementedError

    @classmethod
    def from_dict(cls, data: dict):
        raise NotImplementedError


_type_lookup: dict = {}


def _decode(value, client):
    if value is None:
        return None

    value_class = value.__class__
    if value_class is dict:
        td_type = value.get("@type")
        if td_type is not None:
            obj_type = _type_lookup.get(td_type)
            if obj_type is None:
                obj_type = globals()[pytdbot.utils.to_camel_case(td_type)]
                _type_lookup[td_type] = obj_type
            return obj_type.from_dict(value, client)

        return {key: _decode(child, client) for key, child in value.items()}

    if value_class is list:
        return [_decode(item, client) for item in value]

    return value


