class UserTypeBot(TlObject, UserType):
    r"""A bot \(see https://core\.telegram\.org/bots\)

    Parameters:
        can_be_edited (:class:`bool`):
            True, if the bot is owned by the current user and can be edited using the methods toggleBotUsernameIsActive, reorderBotActiveUsernames, setBotProfilePhoto, setBotName, setBotInfoDescription, and setBotInfoShortDescription

        can_join_groups (:class:`bool`):
            True, if the bot can be invited to basic group and supergroup chats

        can_read_all_group_messages (:class:`bool`):
            True, if the bot can read all messages in basic group or supergroup chats and not just those addressed to the bot\. In private and channel chats a bot can always read all messages

        has_main_web_app (:class:`bool`):
            True, if the bot has the main Web App

        has_topics (:class:`bool`):
            True, if the bot has topics

        has_topic_sidebar (:class:`bool`):
            True, if the bot has topics, which are shown in a sidebar

        allows_users_to_create_topics (:class:`bool`):
            True, if users can create and delete topics in the chat with the bot

        can_manage_bots (:class:`bool`):
            True, if the bot can manage other bots

        is_inline (:class:`bool`):
            True, if the bot supports inline queries

        inline_query_placeholder (:class:`str`):
            Placeholder for inline queries \(displayed in the application input field\)

        supports_guest_queries (:class:`bool`):
            True, if the bot can be queried by username from any non\-secret chat

        is_guard (:class:`bool`):
            True, if the bot can be set as a guard bot in supergroup chats

        need_location (:class:`bool`):
            True, if the location of the user is expected to be sent with every inline query to this bot

        can_connect_to_business (:class:`bool`):
            True, if the bot supports connection to user accounts for chat automation

        can_be_added_to_attachment_menu (:class:`bool`):
            True, if the bot can be added to the attachment or side menu

        active_user_count (:class:`int`):
            The number of recently active users of the bot

    """

    def __init__(
        self,
        *,
        can_be_edited: bool | None = False,
        can_join_groups: bool | None = False,
        can_read_all_group_messages: bool | None = False,
        has_main_web_app: bool | None = False,
        has_topics: bool | None = False,
        has_topic_sidebar: bool | None = False,
        allows_users_to_create_topics: bool | None = False,
        can_manage_bots: bool | None = False,
        is_inline: bool | None = False,
        inline_query_placeholder: str | None = "",
        supports_guest_queries: bool | None = False,
        is_guard: bool | None = False,
        need_location: bool | None = False,
        can_connect_to_business: bool | None = False,
        can_be_added_to_attachment_menu: bool | None = False,
        active_user_count: int | None = 0,
    ) -> None:
        self.can_be_edited = can_be_edited
        r"""True, if the bot is owned by the current user and can be edited using the methods toggleBotUsernameIsActive, reorderBotActiveUsernames, setBotProfilePhoto, setBotName, setBotInfoDescription, and setBotInfoShortDescription"""
        self.can_join_groups = can_join_groups
        r"""True, if the bot can be invited to basic group and supergroup chats"""
        self.can_read_all_group_messages = can_read_all_group_messages
        r"""True, if the bot can read all messages in basic group or supergroup chats and not just those addressed to the bot\. In private and channel chats a bot can always read all messages"""
        self.has_main_web_app = has_main_web_app
        r"""True, if the bot has the main Web App"""
        self.has_topics = has_topics
        r"""True, if the bot has topics"""
        self.has_topic_sidebar = has_topic_sidebar
        r"""True, if the bot has topics, which are shown in a sidebar"""
        self.allows_users_to_create_topics = allows_users_to_create_topics
