class ChatAdministratorRights(TlObject):
    r"""Describes rights of the administrator

    Parameters:
        can_manage_chat (:class:`bool`):
            True, if the administrator can access the chat event log, get the boost list, see hidden supergroup and channel members, report supergroup spam messages, ignore slow mode, and send messages to the chat without paying Telegram Stars\. Implied by any other privilege; applicable to supergroups and channels only

        can_change_info (:class:`bool`):
            True, if the administrator can change the chat title, photo, and other settings

        can_post_messages (:class:`bool`):
            True, if the administrator can create channel posts, approve suggested channel posts, or view channel statistics; applicable to channels only

        can_edit_messages (:class:`bool`):
            True, if the administrator can edit messages of other users and pin messages; applicable to channels only

        can_delete_messages (:class:`bool`):
            True, if the administrator can delete messages of other users

        can_invite_users (:class:`bool`):
            True, if the administrator can invite new users to the chat

        can_restrict_members (:class:`bool`):
            True, if the administrator can restrict, ban, or unban chat members or view supergroup statistics

        can_pin_messages (:class:`bool`):
            True, if the administrator can pin messages; applicable to basic groups and supergroups only

        can_manage_topics (:class:`bool`):
            True, if the administrator can create, rename, close, reopen, hide, and unhide forum topics; applicable to forum supergroups only

        can_promote_members (:class:`bool`):
            True, if the administrator can add new administrators with a subset of their own privileges or demote administrators who were directly or indirectly promoted by them; applicable to supergroups and channels only

        can_manage_video_chats (:class:`bool`):
            True, if the administrator can manage video chats

        can_post_stories (:class:`bool`):
            True, if the administrator can create new chat stories, or edit and delete posted stories; applicable to supergroups and channels only

        can_edit_stories (:class:`bool`):
            True, if the administrator can edit stories posted by other users, post stories to the chat page, pin chat stories, and access the story archive; applicable to supergroups and channels only

        can_delete_stories (:class:`bool`):
            True, if the administrator can delete stories posted by other users; applicable to supergroups and channels only

        can_manage_direct_messages (:class:`bool`):
            True, if the administrator can answer channel direct messages; applicable to channels only

        can_manage_tags (:class:`bool`):
            True, if the administrator can change tags of other users; applicable to basic groups and supergroups only

        can_send_welcome_messages (:class:`bool`):
            True, if the administrator can manage and send welcome messages

        is_anonymous (:class:`bool`):
            True, if the administrator isn't shown in the chat member list and sends messages anonymously; applicable to supergroups only

    """

    def __init__(
        self,
        *,
        can_manage_chat: bool | None = False,
        can_change_info: bool | None = False,
        can_post_messages: bool | None = False,
        can_edit_messages: bool | None = False,
        can_delete_messages: bool | None = False,
        can_invite_users: bool | None = False,
        can_restrict_members: bool | None = False,
        can_pin_messages: bool | None = False,
        can_manage_topics: bool | None = False,
        can_promote_members: bool | None = False,
        can_manage_video_chats: bool | None = False,
        can_post_stories: bool | None = False,
        can_edit_stories: bool | None = False,
        can_delete_stories: bool | None = False,
        can_manage_direct_messages: bool | None = False,
        can_manage_tags: bool | None = False,
        can_send_welcome_messages: bool | None = False,
        is_anonymous: bool | None = False,
    ) -> None:
        self.can_manage_chat = can_manage_chat
        r"""True, if the administrator can access the chat event log, get the boost list, see hidden supergroup and channel members, report supergroup spam messages, ignore slow mode, and send messages to the chat without paying Telegram Stars\. Implied by any other privilege; applicable to supergroups and channels only"""
        self.can_change_info = can_change_info
